changeSet.sql:
create or alter function [dbo].[GetCombinedPermissionsForUserByAssetTypeId] ( @id int, @userId int ) returns int as begin declare @object varchar(50), @objectId int, @defaultPermissions int, @combinedPermissionMask int = 0; select @object = Object, @objectId = ObjectID, @defaultPermissions = [DefaultPermissions] from AssetType where ID = @id;
declare @permissions dbo.Ids;
insert into @permissions select relation.[PermissionsBitMask] from ResponsibilityTypeRelation relation inner join ( select rr.ResponsibilityTypeID from ResponsibilityRuleResultAsset ra inner join ResponsibilityTypeRelationRule rr on rr.ID = ra.RuleID and ra.AssetTypeID = @id and ra.AssetID = 0 inner join ResponsibilityRuleResultSecurityAsset rs on rs.RuleID = rr.ID and rs.SecurityAsset = 'R' and rs.SecurityAssetID = @userId union select rr.ResponsibilityTypeID from ResponsibilityRuleResultAsset ra inner join ResponsibilityTypeRelationRule rr on rr.ID = ra.RuleID and ra.AssetTypeID = @id and ra.AssetID = 0 inner join ResponsibilityRuleResultSecurityAsset rs on rs.RuleID = rr.ID and rs.SecurityAsset = 'G' inner join ResourceGroup rg on rg.GroupID = rs.SecurityAssetID and rg.ResourceID = @userId ) p on p.ResponsibilityTypeID = relation.ResponsibilityTypeID and relation.ObjectType = @object and relation.ObjectID = @objectId;
if not exists (select 1 from @permissions) and @defaultPermissions is not null begin insert into @permissions values(@defaultPermissions) end
if not exists (select Id from @permissions where Id & 1 = 1) begin if @defaultPermissions = 1 begin insert into @permissions values(@defaultPermissions) end else begin if exists (select top 1 1 from [dbo].[ResponsibilitySummary] where AssetTypeID = @id and ApplyToType = 0 and ResourceID = @userId) begin insert into @permissions values(1) end end end
set @combinedPermissionMask = dbo.GetCombinedPermissions(@permissions);
return @combinedPermissionMask end
